<script>
document.addEventListener('DOMContentLoaded',()=>{const box=document.getElementById('yevmiyeSatirlari'),tpl=document.getElementById('yevmiyeSatirSablonu'),add=document.getElementById('satirEkle');if(!box||!tpl||!add)return;let index=0;const render=()=>{let b=0,a=0;box.querySelectorAll('.borc-input').forEach(x=>b+=Number(x.value||0));box.querySelectorAll('.alacak-input').forEach(x=>a+=Number(x.value||0));document.getElementById('borcToplam').textContent='₺'+b.toLocaleString('tr-TR',{minimumFractionDigits:2});document.getElementById('alacakToplam').textContent='₺'+a.toLocaleString('tr-TR',{minimumFractionDigits:2});document.getElementById('farkToplam').textContent='₺'+(b-a).toLocaleString('tr-TR',{minimumFractionDigits:2});};const addRow=()=>{box.insertAdjacentHTML('beforeend',tpl.innerHTML.replaceAll('__I__',index++));render();};add.addEventListener('click',addRow);box.addEventListener('input',render);box.addEventListener('click',e=>{if(e.target.closest('.remove-row')){e.target.closest('.gm-journal-row').remove();render();}});addRow();addRow();});
</script>
